// Block (composition) — selectable in-app subscription plan cards.
// Existing Card, Badge, and Button variants own all visual treatment.
import type { Ref } from "react";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Card } from "../components/Card";
import { Grid } from "../layouts/Grid";
import { Stack } from "../layouts/Stack";
import "./PlanSelector.css";

export interface PlanSelectorProps {
  plans: {
    id: string;
    name: string;
    price: string;
    period?: string;
    features: string[];
    current?: boolean;
    featured?: boolean;
  }[];
  onSelect?: (id: string) => void;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function PlanSelector({ plans, onSelect, className, ref }: PlanSelectorProps) {
  const desktopColumns = Math.min(Math.max(plans.length, 1), 3);

  // A grid of bordered Cards: the gutter is token-contract.md's card-grid row, as in `PricingTable`.
  return (
    <Grid
      as="section"
      ref={ref}
      aria-label="Subscription plans"
      columns={{ small: 1, medium: desktopColumns }}
      gap="medium"
      className={className ? `sd-planselector ${className}` : "sd-planselector"}
    >
      {plans.map((plan) => (
        <Card key={plan.id}>
          <Stack gap="small" className="sd-planselector__content">
            {/* The plan name and its price are ONE unit, at a tighter rung than the card's
                own, the pair `ProductCard` already groups. Flat, the same 8px separated the
                name from its price as separated that price from the feature list below it. */}
            <Stack gap="x-small" className="sd-planselector__header">
              <Stack direction="row" align="center" gap="x-small" wrap className="sd-planselector__heading">
                <><h3 className="sd-planselector__name sd-type-title-medium">{plan.name}</h3></>
                {plan.featured && <Badge variant="tonal">Popular</Badge>}
                {plan.current && <Badge>Current</Badge>}
              </Stack>
              <>
                <p className="sd-planselector__price sd-type-headline-medium">
                  {plan.price}
                  {plan.period && (
                    <small className="sd-planselector__period sd-type-caption-medium">
                      {plan.period}
                    </small>
                  )}
                </p>
              </>
            </Stack>
            {/* spacing: attachment — the plan's name and price head the features it lists */}
            <ul className="sd-planselector__features sd-type-body-medium">
              {plan.features.map((feature) => (
                <li key={feature}>{feature}</li>
              ))}
            </ul>
            <Button
              variant={plan.featured ? "primary" : "secondary"}
              isDisabled={plan.current}
              onPress={() => onSelect?.(plan.id)}
            >
              {plan.current ? "Current plan" : "Choose"}
            </Button>
          </Stack>
        </Card>
      ))}
    </Grid>
  );
}

/* PlanSelector.css — .sd-planselector (Block)
   Arrangement only: full-width grid and native text/list spacing normalization. */
.sd-planselector {
  width: 100%;
}

.sd-planselector__name,
.sd-planselector__price,
.sd-planselector__features {
  margin: 0;
}

.sd-planselector__period {
  margin-inline-start: var(--sd-space-2x-small);
}

.sd-planselector__features {
  padding-inline-start: var(--sd-space-large);
}
